data.custom_css:
.translate { position: absolute; top: 5px; right: 5px; }

.event-description.bg-body img {
  margin-top: 1em;
  max-width: 100%;
}

.challenge-badge {
  display: block;
  float: none;
  width: 100%;
  background-position: center;
}
#readme-md::before {
  content: 'README';
  width: 100%;
  display: block;
  text-align: center;
  font-size: large;
  font-family: monospace;
  font-weight: bold;
  color: white;
  background: lightblue;
  padding: 1em;
  margin: 0.5em 0;
}

.project-home .project-image-container {
  margin-top: 0px !important;
}

.bg-body table td {
  padding: 9px;
  border: 1px solid lightblue;
}
.bg-body table th {
  text-align: center;
  color: lightblue;
}
